//! `sermofur_core::guid::try_parse` against `Guid.TryParse` of .NET
//! (`rust/tests/golden/guid.json`, regenerated by `rust/tools/guid-oracle`): for every form, the
//! answer and the value read, in the D format.

use std::path::PathBuf;

use serde_json::Value;
use sermofur_core::guid::try_parse;

#[test]
fn every_form_reads_like_dotnet() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/golden/guid.json");
    let golden: Value =
        serde_json::from_str(&std::fs::read_to_string(path).expect("guid.json")).expect("JSON");
    let cases = golden["cases"].as_array().expect("cases");
    let mut failures = Vec::new();
    for case in cases {
        let input = case["input"].as_str().expect("input");
        let expected = case["value"].as_str().map(str::to_owned);
        let actual = try_parse(input).map(|id| id.hyphenated().to_string());
        assert_eq!(case["ok"].as_bool(), Some(expected.is_some()), "{input:?}");
        if actual != expected {
            failures.push(format!("{input:?}: expected {expected:?}, got {actual:?}"));
        }
    }
    eprintln!("{} GUID forms compared", cases.len());
    assert!(failures.is_empty(), "differences:\n{}", failures.join("\n"));
}
